def _asignar_contenedor_por_defecto(apps, schema_editor):
    """
    Los ítems previos a esta migración no tenían contenedor.

    Se les asigna un contenedor provisorio por embarque para poder volver
    el campo obligatorio sin perder información; el usuario puede corregirlo
    desde la pantalla del embarque.
    """
    EmbarqueItem = apps.get_model('importaciones', 'EmbarqueItem')
    EmbarqueContenedor = apps.get_model('importaciones', 'EmbarqueContenedor')

    for item in EmbarqueItem.objects.filter(contenedor__isnull=True):
        contenedor, _ = EmbarqueContenedor.objects.get_or_create(
            embarque_id=item.embarque_id,
            numero='SIN-DEFINIR',
            defaults={
                'tipo': 'PENDIENTE',
                'observaciones': 'Contenedor provisorio generado por la migración 0009.',
            },
        )
        item.contenedor_id = contenedor.pk
        item.save(update_fields=['contenedor'])


